package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

func main() {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) { fmt.Fprint(w, "small body") }))
	defer server.Close()
	resp, err := server.Client().Get(server.URL)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	body, err := io.ReadAll(io.LimitReader(resp.Body, 1024))
	if err != nil {
		panic(err)
	}
	fmt.Println(string(body))
}
```
The limit protects memory and the deferred Close covers every later return in this small operation.

```go
package main

import (
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

type Reply struct {
	Name string `json:"name"`
}

func main() {
	server := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		fmt.Fprint(w, `{"name":"Mira"}`)
	}))
	defer server.Close()
	resp, err := server.Client().Get(server.URL)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	const limit = 1024
	b, err := io.ReadAll(io.LimitReader(resp.Body, limit+1))
	if err != nil {
		panic(err)
	}
	if len(b) > limit {
		panic("response too large")
	}
	var reply Reply
	if err := json.Unmarshal(b, &reply); err != nil {
		panic(err)
	}
	fmt.Println(reply.Name)
}
```
Reading one byte beyond the limit distinguishes an exact-limit document from truncated oversized input.

```go
package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"net/http/httptest"
)

type Reply struct {
	Count int `json:"count"`
}

func fetch(client *http.Client, url string) error {
	resp, err := client.Get(url)
	if err != nil {
		return fmt.Errorf("transport: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return fmt.Errorf("HTTP status %d", resp.StatusCode)
	}
	var reply Reply
	if err := json.NewDecoder(resp.Body).Decode(&reply); err != nil {
		return fmt.Errorf("decode JSON: %w", err)
	}
	return nil
}

func main() {
	s := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, _ *http.Request) {
		w.WriteHeader(502)
		fmt.Fprint(w, `{"error":"upstream"}`)
	}))
	defer s.Close()
	fmt.Println(fetch(s.Client(), s.URL))
}
```
The local server completes HTTP with status 502, so fetch reports a status failure rather than a transport or JSON failure.
